<?php $setups=$_SESSION['webhook_setups']??[]; if(isset($_SESSION['webhook_setup'])) $setups[]=$_SESSION['webhook_setup']; unset($_SESSION['webhook_setups'],$_SESSION['webhook_setup']); foreach($setups as $setup): ?><div class="notice"><div><strong>Configuration du webhook<?= isset($setup['repository'])?' · '.e($setup['repository']):'' ?> — à conserver maintenant</strong><p>URL : <code><?= e($setup['url']) ?></code></p><p>Secret : <code><?= e($setup['secret']) ?></code></p><small>Activez les événements push et pull request. Le secret sera masqué lors des prochaines visites.</small></div></div><?php endforeach; ?>
<div class="feature-banner development-banner"><span class="feature-orb"><?= icon('code') ?></span><div><span class="eyebrow">DU TICKET AU CODE</span><h2>Les idées et le code, reliés.</h2><p>Ajoutez la clé d’un ticket dans une branche, un commit ou une pull request.<br>Sillage rassemble le contexte au même endroit.</p></div><?php if($user['role']==='admin'): ?><button class="button primary" data-open="connection-dialog"><?= icon('plus') ?>Connecter un dépôt</button><?php endif; ?></div>
<div class="tabs development-tabs"><button class="selected" data-dev-tab="connections">Connexions <span><?= count($connections) ?></span></button><?php foreach(App\Services\DevelopmentPayload::KINDS as $kind=>$label): ?><button data-dev-tab="<?= e($kind) ?>"><?= e($label) ?></button><?php endforeach; ?><button data-dev-tab="repositories">Dépôts</button></div><section data-dev-panel="connections"><div class="connection-grid"><?php foreach(['github'=>['GitHub','GH','Du code à la collaboration.'],'bitbucket'=>['Bitbucket','BB','Vos dépôts, au plus près des projets.']] as $provider=>[$name,$mark,$desc]): $connected=array_filter($connections,fn($c)=>$c['provider']===$provider); ?><article class="panel connection-card"><div class="provider-mark"><?= e($mark) ?></div><h2><?= e($name) ?></h2><p><?= e($desc) ?></p><span class="pill <?= $connected?'success':'neutral' ?>"><?= $connected?count($connected).' dépôt(s) connecté(s)':'À connecter' ?></span><?php if($user['role']==='admin'): ?><button class="button subtle" data-open="<?= $connected?'provider-settings-'.e($provider):'connection-dialog' ?>" <?= !$connected?'data-connection-provider="'.e($provider).'"':'' ?>>Configurer <?= icon('arrow') ?></button><?php endif; ?></article><?php endforeach; ?></div><p class="help-text">Synchronisez branches, commits ou pull requests par pages de 50 depuis l’onglet Dépôts. Les webhooks signés transmettent les changements en continu et peuvent déclencher vos règles. Leurs URL doivent être accessibles au fournisseur. Les builds et déploiements seront ajoutés dans une étape suivante.</p></section>
<?php foreach(App\Services\DevelopmentPayload::KINDS as $kind=>$label): ?><section data-dev-panel="<?= e($kind) ?>" hidden><div class="panel"><h2><?= e($label) ?></h2><?php $filteredEvents=array_filter($events,fn($e)=>$e['kind']===$kind); foreach($filteredEvents as $event): ?><div class="dev-event"><span class="type-icon type-story"><?= icon('code') ?></span><div><a href="<?= e($event['external_url']) ?>" target="_blank" rel="noopener"><?= e($event['title']) ?></a><small><?= e($event['repository']) ?> · <?= ($event['metadata']['date_known']??true)?e($event['occurred_at']):'Date non fournie' ?></small></div><span class="pill neutral"><?= e($event['state_label']) ?></span><?php foreach($event['ticket_refs'] as $ref): ?><a class="ticket-key" href="<?= e(ticket_url((int)$ref['id'])) ?>"><?= e($ref['key']) ?></a><?php endforeach; ?></div><?php endforeach; if(!$filteredEvents): ?><div class="mini-empty"><?= icon('code') ?><p>Aucun événement reçu pour le moment.</p></div><?php endif; ?></div></section><?php endforeach; ?>
<section data-dev-panel="repositories" hidden><div class="panel"><h2>Vos dépôts</h2><?php foreach($connections as $c): ?><div class="repository-row"><span class="provider-mark small"><?= $c['provider']==='github'?'GH':'BB' ?></span><div><strong><?= e($c['repository']) ?></strong><small>Dernière synchronisation : <?= e($c['last_sync_at']??'jamais') ?></small></div><?php if($user['role']==='admin'): ?><form method="post" action="/connections/<?= (int)$c['id'] ?>/sync"><?= csrf() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><label>Éléments<select name="kind"><?php foreach(App\Services\DevelopmentPayload::KINDS as $kind=>$label): ?><option value="<?= e($kind) ?>" <?= $kind==='pull_request'?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>Page<input type="number" name="page" min="1" max="10000" value="1" class="sync-page"></label><button class="button subtle">Synchroniser</button></form><form method="post" action="/connections/<?= (int)$c['id'] ?>/delete"><?= csrf() ?><input type="hidden" name="project_id" value="<?= (int)$project['id'] ?>"><button class="text-button danger" data-confirm="Détacher ce dépôt du projet ? La connexion partagée est conservée si d’autres projets l’utilisent ; sinon son historique local sera supprimé.">Détacher</button></form><?php endif; ?></div><?php endforeach; if(!$connections): ?><p class="muted">Connectez votre premier dépôt pour retrouver son activité ici.</p><?php endif; ?></div></section>
